// PIPELINE RUN A - a change passes every test, but contains a genuine
// TypeScript type error in a file the test suite doesn't directly cover

// Stage: test          >> PASS (47 tests, 8 seconds)
// Stage: build          >> FAIL (TypeScript compilation error:
//                           Property 'x' does not exist on type 'Y')
//
// PIPELINE STOPS HERE. The deploy stage's 'needs: build' dependency
// means it NEVER EVEN RUNS, since build genuinely failed - exactly
// the protection Module 21's test-only gating, by itself, could NOT
// have provided, since the tests themselves had already passed
// completely before this genuine build failure was even discovered.

// PIPELINE RUN B - a genuinely correct, deployable change

// Stage: test    >> PASS (47 tests, 8 seconds)
// Stage: build    >> PASS (TypeScript compiles, Docker image builds
//                    and pushes successfully, 95 seconds)
// Stage: deploy   >> PASS (deploy.sh runs successfully, 40 seconds)
//
// ALL THREE stages passed - this change is now genuinely, safely
// running in production, having passed Module 21's testing gate AND
// this lesson's genuinely additional build-success gate.

// config.ts - loaded once at application startup
const environment = process.env.NODE_ENV || 'development';

interface AppConfig {
  databaseUrl: string;
  stripeKey: string;
  isProd: boolean;
}

function loadConfig(): AppConfig {
  // In each ACTUAL environment, these process.env values are set
  // differently - locally via .env.development, in CI/CD via
  // lesson 3's secrets injection, exactly matching the genuinely
  // running environment, without this code itself ever needing to
  // know or care which specific environment it's currently in
  const databaseUrl = process.env.DATABASE_URL;
  const stripeKey = process.env.STRIPE_KEY;

  if (!databaseUrl || !stripeKey) {
    // FAIL LOUDLY AND IMMEDIATELY if genuinely required configuration
    // is missing, rather than allowing the application to start in a
    // silently broken, partially-configured state
    throw new Error(`Missing required environment variables for environment: ${environment}`);
  }

  return {
    databaseUrl,
    stripeKey,
    isProd: environment === 'production'
  };
}

export const config = loadConfig();

// Usage elsewhere in the application - genuinely environment-agnostic
// code, simply trusting that config.databaseUrl is already correctly
// set for whatever environment is actually currently running
import { MongoClient } from 'mongodb';
const client = new MongoClient(config.databaseUrl);

